int core_power(int nb, int start_number, int res, int bit)
{
    while (bit > start_number) {
        bit /= 4;
    }
    while (bit > 0) {
        if (start_number >= res + bit) {
            start_number -= res + bit;
            res = (res / 2) + bit;
        } else {
            res /= 2;
        }
        bit /= 4;
    }
    return res;
}

