const long LIMIT = 2147483647;

static int determine_sign(char const *str, int num_start)
{
    int sign = 0;

    for (int i = num_start - 1; i >= 0; --i) {
        if (str[i] == '+')
            continue;
        if (str[i] != '-')
            return sign;
        if (!sign)
            sign = 1;
        else
            sign = 0;
    }
    return sign;
}

