    return ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'));
}

char to_upper(char c)
{
    if (c >= 'a' && c <= 'z') {
        return c - ('a' - 'A');
    }
    return c;
}

char *my_strcapitalize(char *str)
{
    int capitalize_next = 1;

    for (int i = 0; str[i] != '\0'; i++) {
        if (is_letter(str[i])) {
            if (capitalize_next) {
                str[i] = to_upper(str[i]);
                capitalize_next = 0;
            } else {
                str[i] = to_upper(str[i]);
            }
        } else {
            capitalize_next = 1;
        }
    }
    return str;
}

