__attribute((access(write_only, 1), nonnull))
static void place_rook(char *board, int size, int column, int row)
{
    for (int i = 0; i < size; i++) {
        board[i * size + row] = 1;
        board[column * size + i] = 1;
    }
}

__attribute((access(write_only, 1), nonnull))
static void mark_if_in_bounds(char *board, int size, int column, int row)
{
    if (column >= 0 && column < size && row >= 0 && row < size)
        board[column * size + row] = 1;
}

__attribute((access(write_only, 1), nonnull, unused))
static void place_bishop(char *board, int size, int column, int row)
{
    for (int i = 0; i < size; i++) {
        mark_if_in_bounds(board, size, column - i, row - i);
        mark_if_in_bounds(board, size, column - i, row + i);
        mark_if_in_bounds(board, size, column + i, row - i);
        mark_if_in_bounds(board, size, column + i, row + i);
    }
}

__attribute((access(write_only, 1), nonnull))
static void place_queen(char *board, int size, int column, int row)
{
    place_rook(board, size, column, row);
    place_bishop(board, size, column, row);
    board[column * size + row] = 2;
}

__attribute((access(read_write, 3), access(read_write, 4), nonnull))
static void place_next_queen(
    int queens_placed, int size, char *board, int *position_count)
{
    int column = queens_placed;
    char *working_copy;

    if (queens_placed == size) {
        (*position_count)++;
        return;
    }
    working_copy = __builtin_alloca(size * size * sizeof(char));
    for (int row = 0; row < size; row++) {
        my_memcpy(working_copy, board, size * size * sizeof(char));
        if (is_queen_placement_possible(
                working_copy, size * size, column * size + row)) {
            place_queen(working_copy, size, column, row);
            place_next_queen(
                queens_placed + 1, size, working_copy, position_count);
        }
    }
}

