        if (array[j - p][i + p] == 1)
            return (0);
        p++;
    }
    p = 0;
    while (j + p < n && i - p >= 0) {
        if (array[j + p][i - p] == 1)
            return (0);
        p++;
    }
    p = 0;
    while (i - p >= 0 && j - p >= 0) {
        if (array[i - p][j - p] == 1)
            return (0);
        p++;
    }
    return (1);
}

