int my_putnbr_base(int nb, char const *base)
{
    int base_number = my_strlen(base);
    const unsigned int total_number_of_digits =
        count_number_of_digits(nb, base_number);
    unsigned int current_digit_from_end = total_number_of_digits;
    int temporary_number = 0;

    manage_negative_number(nb);
    while (current_digit_from_end > 0) {
        current_digit_from_end --;
        temporary_number = nb / (power(base_number, current_digit_from_end));
        my_putchar(convert_digit_to_ascii(
            modulo(temporary_number, base_number), base));
    }
    if (total_number_of_digits == 0) {
        my_putchar('0');
    }
    return (0);
}

