    int tpmp = nb;

    if (nb == 0) {
        return 1;
    } else if (nb < 0 || nb > 12) {
        return 0;
    }
    if (nb > 0) {
        nb -= 1;
        while (nb != 0) {
            tpmp = tpmp * nb;
            nb -= 1;
        }
    }
    nb = tpmp;
    return nb;
}

