int my_compute_factorial_it(int nb)
{
    int nbf;
    nbf = nb;
    if (nb < 0) {
        return 0;
    } else if (nb == 0 || nb == 1) {
        return 1;
    } else {
        while (nb > 1) {
            fnb = nbf * (nb - 1);
            nb--;
            return fnb;
        }
    }
}

