    return (-1);
}

int my_getnbr_base(char const *str, char const *base)
{
    int result = 0;
    int base_len = my_getnbr_strlen(base);
    int sign = 1;
    int digit;

    if (str == 0 || base == 0)
        return (0);
    while (*str == '-' || *str == '+') {
        if (*str == '-')
            sign = -sign;
        str++;
    }
    while (*str != '\0') {
        digit = getnbr_char_to_digit(*str);
        if (digit < 0 || digit >= base_len)
            return (-1);
        result = result * base_len + digit;
        str++;
    }
    return (result * sign);
}

