int count_valid_queens_placements_helper(int *queens, int row, int n)
{
    int col;
    int count = 0;

    if (row == n) {
        return 1;
    }
    for (col = 0; col < n; col++) {
        if (is_valid(queens, row, col)) {
            queens[row] = col;
            count += count_valid_queens_placements_helper(queens, row + 1, n);
            queens[row] = -1;
        }
    }
    return count;
}

int is_valid(int *queens, int row, int col)
{
    int i;
    int diff1;
    int diff2;

    for (i = 0; i < row; i++) {
        diff1 = queens[i] - i;
        diff2 = queens[i] + i;
        if (queens[i] == col || diff1 == col - row || diff2 == col + row) {
            return 0;
        }
    }
    return 1;
}

