__attribute((const))
static int square_root_floor(int nb)
{
    int sqrt = 1;
    int test;

    while (!__builtin_smul_overflow(sqrt, sqrt, &test) && test <= nb) {
        sqrt++;
    }
    if (test == nb)
        return sqrt;
    return sqrt - 1;
}

__attribute((const))
int my_is_prime(int nb)
{
    int max_prime;

    if (nb < 0)
        nb *= -1;
    max_prime = square_root_floor(nb);
    if (nb == 2)
        return 1;
    if (nb < 2 || nb % 2 == 0)
        return 0;
    for (int test = 3; test <= max_prime; test += 2) {
        if (nb % test != 0)
            continue;
        if (my_is_prime(test))
            return 0;
    }
    return 1;
}

