bool can_place_queen(int *grid, uint row, uint col, uint n)
{
    bool is_safe = 1;

    for (uint i = 0; i < row; i++) {
        if (grid[i] == col)
            is_safe = 0;
        if (!is_diagonal_safe(grid, i, row, col))
            is_safe = 0;
    }
    return is_safe;
}

void solve_with_backtrack(int *grid, uint row, uint *count, uint n)
{
    if (row >= n)
        (*count)++;
    for (uint i = 0; i < n; i++) {
        if (can_place_queen(grid, row, i, n)) {
            grid[row] = i;
            solve_with_backtrack(grid, row + 1, count, n);
        }
    }
}

