static int get_sign(char const **str)
{
    int minus_count = 0;

    while (**str) {
        switch (**str) {
        case '-':
            minus_count++;
            break;
        case '+':
            break;
        default:
            return minus_count % 2 ? -1 : 1;
        }
        (*str)++;
    }
    return 0;
}

