{
    const int min = -2147483648;
    const int max = 2147483647;
    long long int number = (long long int)nb;

    return ((number * n) < min || (number * n) > max);
}

int factorial(int n)
{
    int number = 1;

    if (n == 0) {
        return (1);
    }
    number = factorial(n - 1);
    if (is_overflowing(number, n)) {
        return (0);
    }
    number *= n;
    return (number);
}

