    int sign;
    int result = 0;
    int i = 0;
    int j;

    if (len < 2) {
        return 0;
    }
    sign = get_sign(str, &i);
    while (str[i] != '\0') {
        j = get_index(str, base, &i);
        if (base[j] == '\0') {
