int rien(int i, int a, char *str, char *to_find)
{
    int cmp = 0;

    if (str[i] == '\0') {
        return 1;
    }
    a = count(to_find);
    cmp = count(str);
    if (i + a > cmp || str[i + a] == '\0') {
        return 1;
    }
}

int loop(int i, int a, char *str, char *to_find)
{
    while (str[i + a - 1] == to_find[a - 1]) {
        a--;
        if (to_find[a] == to_find[0]) {
            return a;
        }
    }
    return a;
}

