int is_upper_diag_safe(int board[], int row, int col, int n)
{
    int i = row;
    int j = col;

    while (i >= 0 && j >= 0) {
        if (board[i * n + j] == 1)
            return 0;
        i--;
        j--;
    }
    return 1;
}

int is_lower_diag_safe(int board[], int row, int col, int n)
{
    int i = row;
    int j = col;

    while (i < n && j >= 0) {
        if (board[i * n + j] == 1)
            return 0;
        i++;
        j--;
    }
    return 1;
}

int is_safe(int board[], int row, int col, int n)
{
    int is_col = -1;
    int is_upper_diag = is_upper_diag_safe(board, row, col, n);
    int is_lower_diag = is_lower_diag_safe(board, row, col, n);

    for (int i = 0; i < col; i++) {
        if (board[row * n + i] == 1)
            is_col = 0;
    }
    is_col = is_col == 0 ? is_col : 1;
    return is_col && is_upper_diag && is_lower_diag;
}

int solve_n_queens(int *board, int col, int n)
{
    int count = 0;

    if (col == n)
        return 1;
    for (int i = 0; i < n; i++) {
        if (is_safe(board, i, col, n)) {
            board[i * n + col] = 1;
            count += solve_n_queens(board, col + 1, n);
            board[i * n + col] = 0;
        }
    }
    return count;
}

int count_valid_queens_placements(int n)
{
    int board[n][n];

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            board[i][j] = 0;
        }
    }
    return solve_n_queens(*board, 0, n);
}

