int my_backtracking_core(int col, int size, int *chess)
{
    int total = 0;

    if (col == size) {
        return 1;
    }
    for (int recu = 0; recu < size; recu++) {
        if (!is_possible(col, recu, chess, size)) {
            chess[col] = recu;
            total += my_backtracking_core(col + 1, size, chess);
            chess[col] = -20;
        }
    }
    return total;
}

int is_possible(int row, int column, int *chess, int size)
{
    int diagL = column - 1;
    int diagR = column + 1;

    for (int index = 0; index < row; index++) {
        if (chess[index] == column) {
            return 1;
        }
    }
    for (int prevRow = row - 1; prevRow >= 0; prevRow--) {
        if (chess[prevRow] == diagL || chess[prevRow] == diagR) {
            return 1;
        }
        diagL--;
        diagR++;
    }
    return 0;
}

