static int add_place_state(int n, int i, int state, int map)
{
    int number_to_add = 0;
    int new_state = 0;
    int current_state = 0;

    if (i < 0 || i >= n) {
        return (map);
    }
    current_state = get_place_state(i, map);
    new_state = (!is_state_in_mix(current_state, state)) * state;
    number_to_add = new_state * my_compute_power_it(9, i);
    return (map + number_to_add);
}

static int find_next_valid_place_given_map(int n, int map, int previous_place)
{
    int i = 0;

    if (previous_place == (n - 1)) {
        return (-1);
    }
    while (i < n) {
        if (get_place_state(i, map) == 0) {
            return (i);
        }
        i++;
    }
    return (-1);
}

static int continue_attack(int n, int map)
{
    int i = 0;
    int state = 0;
    int exit_map = 0;

    while (i < n) {
        state = get_place_state(i, map);
        if (is_state_in_mix(state, 1)) {
            exit_map = add_place_state(n, i, 1, exit_map);
        }
        if (is_state_in_mix(state, 2)) {
            exit_map = add_place_state(n, i - 1, 2, exit_map);
        }
        if (is_state_in_mix(state, 4)) {
            exit_map = add_place_state(n, i + 1, 4, exit_map);
        }
        i++;
    }
    return (exit_map);
}

static int compute_row(int n, int row_id, int entry_map, int *nbr_valid_end)
{
    int exit_map = 0;
    int valid_place = find_next_valid_place_given_map(n, entry_map, -1);

    while (valid_place != -1) {
        exit_map = continue_attack(n, entry_map);
        exit_map = add_place_state(n, valid_place + 1, 4, exit_map);
        exit_map = add_place_state(n, valid_place - 1, 2, exit_map);
        exit_map = add_place_state(n, valid_place, 1, exit_map);
        if (row_id == n - 1) {
            *nbr_valid_end += 1;
        } else {
            compute_row(n, row_id + 1, exit_map, nbr_valid_end);
        }
        entry_map = add_place_state(n, valid_place, 8, entry_map);
        valid_place = find_next_valid_place_given_map(n,
            entry_map, valid_place);
    }
    return (valid_place);
}

